/**
 * Machine-readable documentation for AI agents (`docs/llms.txt` and
 * `docs/llms-full.txt`), generated by `packages/site-runtime/build-docs.ts`
 * from the same Diátaxis documents and live-evaluated examples as `docs.html`.
 */

export const SITE_URL = "https://lionlang.dev";
export const REPO_URL = "https://github.com/andrueandersoncs/lion";

export interface PackageVersions {
  readonly cli: string;
  readonly core: string;
  readonly typesafeAi: string;
  readonly ui: string;
}

export interface LlmsExample {
  readonly error?: string;
  readonly name: string;
  readonly ok: boolean;
  readonly source: string;
  readonly value?: string;
}

export interface LlmsDoc {
  readonly examples: readonly LlmsExample[];
  readonly id: string;
  readonly kindLabel: string;
  readonly kindTitle: string;
  readonly rawBody: string;
  readonly summary: string;
  readonly title: string;
}

export interface LlmsKindGroup {
  readonly docs: readonly {
    readonly id: string;
    readonly summary: string;
    readonly title: string;
  }[];
  readonly title: string;
}

const decodeEntities = (text: string) =>
  text
    .replaceAll("&lt;", "<")
    .replaceAll("&gt;", ">")
    .replaceAll("&quot;", '"')
    .replaceAll("&#39;", "'")
    .replaceAll("&apos;", "'")
    .replaceAll("&nbsp;", " ")
    .replaceAll("&amp;", "&");

const LEADING_BLANK_LINES = /^\s*\n/;
const TRAILING_SPACE = /\s+$/;
const INDENT = /^ */;

const dedent = (text: string) => {
  const lines = text
    .replace(LEADING_BLANK_LINES, "")
    .replace(TRAILING_SPACE, "")
    .split("\n");
  const indents = lines
    .filter((line) => line.trim() !== "")
    .map((line) => line.match(INDENT)?.[0].length ?? 0);
  const indent = indents.length > 0 ? Math.min(...indents) : 0;
  return lines.map((line) => line.slice(indent)).join("\n");
};

const renderInline = (html: string): string => {
  let out = html;
  out = out.replace(
    /<a\s+[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/a>/gi,
    (_, href: string, inner: string) => {
      const target = decodeEntities(href);
      const url = target.startsWith("#")
        ? `${SITE_URL}/docs.html${target}`
        : target;
      return `[${renderInline(inner)}](${url})`;
    }
  );
  out = out.replace(
    /<(?:code|kbd)[^>]*>([\s\S]*?)<\/(?:code|kbd)>/gi,
    (_, inner: string) => `\`${decodeEntities(inner.replace(/<[^>]+>/g, ""))}\``
  );
  out = out.replace(
    /<strong[^>]*>([\s\S]*?)<\/strong>/gi,
    (_, inner: string) => `**${renderInline(inner)}**`
  );
  out = out.replace(
    /<em[^>]*>([\s\S]*?)<\/em>/gi,
    (_, inner: string) => `*${renderInline(inner)}*`
  );
  out = out.replace(/<br\s*\/?>/gi, " ");
  out = out.replace(/<[^>]+>/g, "");
  return decodeEntities(out).replace(/\s+/g, " ").trim();
};

const renderTable = (tableHtml: string): string => {
  const rows: string[][] = [];
  for (const rowMatch of tableHtml.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)) {
    const cells: string[] = [];
    for (const cellMatch of (rowMatch[1] ?? "").matchAll(
      /<(?:th|td)[^>]*>([\s\S]*?)<\/(?:th|td)>/gi
    )) {
      cells.push(renderInline(cellMatch[1] ?? "").replaceAll("|", "\\|"));
    }
    if (cells.length > 0) {
      rows.push(cells);
    }
  }
  if (rows.length === 0) {
    return "";
  }
  const width = Math.max(...rows.map((row) => row.length));
  const padded = rows.map((row) => [
    ...row,
    ...Array.from({ length: Math.max(0, width - row.length) }, () => ""),
  ]);
  const [header, ...body] = padded;
  const lines = [
    `| ${(header ?? []).join(" | ")} |`,
    `| ${Array.from({ length: width }, () => "---").join(" | ")} |`,
    ...body.map((row) => `| ${row.join(" | ")} |`),
  ];
  return `\n\n${lines.join("\n")}\n\n`;
};

const renderDefinitionList = (dlHtml: string): string => {
  const blocks: string[] = [];
  const token = /<(dt|dd)[^>]*>([\s\S]*?)<\/\1>/gi;
  for (const match of dlHtml.matchAll(token)) {
    const tag = (match[1] ?? "").toLowerCase();
    const inner = match[2] ?? "";
    if (tag === "dt") {
      blocks.push(`\n#### ${renderInline(inner)}\n`);
    } else {
      blocks.push(`${htmlToMarkdown(inner)}\n`);
    }
  }
  return `\n${blocks.join("\n")}\n`;
};

const renderList = (listHtml: string, ordered: boolean): string => {
  const items: string[] = [];
  let index = 0;
  for (const match of listHtml.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)) {
    index += 1;
    const prefix = ordered ? `${index}. ` : "- ";
    items.push(`${prefix}${renderInline(match[1] ?? "")}`);
  }
  return `\n\n${items.join("\n")}\n\n`;
};

const EXAMPLE_TAG = /<lion-example([^>]*)>([\s\S]*?)<\/lion-example>/g;
const CODE_BLOCK_TAG = /<code-block([^>]*)>([\s\S]*?)<\/code-block>/g;
const LANG_ATTR = /lang="([^"]*)"/;

/**
 * Converts a documentation fragment's HTML into clean Markdown. When
 * `examples` are supplied, each `<lion-example>` is replaced with its source
 * and live-evaluated output.
 */
export const htmlToMarkdown = (
  html: string,
  examples: readonly LlmsExample[] = []
): string => {
  const fencedBlocks: string[] = [];
  const stash = (block: string) => {
    const token = `@@LIONBLOCK${fencedBlocks.length}@@`;
    fencedBlocks.push(block);
    return `\n\n${token}\n\n`;
  };

  let out = html;
  let exampleIndex = 0;

  out = out.replace(EXAMPLE_TAG, (_, _attrs: string, code: string) => {
    const evaluated = examples[exampleIndex];
    exampleIndex += 1;
    const source = evaluated?.source ?? dedent(decodeEntities(code));
    if (!evaluated) {
      return stash(`\`\`\`json\n${source}\n\`\`\``);
    }
    const label = evaluated.ok ? "Result" : "Error";
    const output = evaluated.ok
      ? (evaluated.value ?? "")
      : (evaluated.error ?? "");
    const fence = evaluated.ok ? "json" : "text";
    return stash(
      `**Example: ${evaluated.name}**\n\n\`\`\`json\n${source}\n\`\`\`\n\n${label}:\n\n\`\`\`${fence}\n${output}\n\`\`\``
    );
  });

  out = out.replace(CODE_BLOCK_TAG, (_, attrs: string, code: string) => {
    const lang = LANG_ATTR.exec(attrs)?.[1] ?? "";
    const body = dedent(decodeEntities(code));
    return stash(`\`\`\`${lang}\n${body}\n\`\`\``);
  });

  out = out.replace(/<docs-map\s*><\/docs-map>/gi, "");

  out = out.replace(/<table[^>]*>[\s\S]*?<\/table>/gi, (match) =>
    stash(renderTable(match).trim())
  );

  out = out.replace(/<dl[^>]*>([\s\S]*?)<\/dl>/gi, (_, inner: string) =>
    renderDefinitionList(inner)
  );

  out = out.replace(
    /<div\s+[^>]*class="[^"]*\bnote\b[^"]*"[^>]*>([\s\S]*?)<\/div>/gi,
    (_, inner: string) => {
      const text = htmlToMarkdown(inner)
        .split("\n")
        .map((line) => (line ? `> ${line}` : ">"))
        .join("\n");
      return `\n\n${text}\n\n`;
    }
  );

  out = out.replace(
    /<h([2-4])[^>]*>([\s\S]*?)<\/h\1>/gi,
    (_, level: string, inner: string) =>
      `\n\n${"#".repeat(Number(level) + 1)} ${renderInline(inner)}\n\n`
  );

  out = out.replace(/<ul[^>]*>([\s\S]*?)<\/ul>/gi, (_, inner: string) =>
    renderList(inner, false)
  );
  out = out.replace(/<ol[^>]*>([\s\S]*?)<\/ol>/gi, (_, inner: string) =>
    renderList(inner, true)
  );

  out = out.replace(
    /<p[^>]*>([\s\S]*?)<\/p>/gi,
    (_, inner: string) => `\n\n${renderInline(inner)}\n\n`
  );

  out = out.replace(/<[^>]+>/g, "");
  out = decodeEntities(out);

  for (let i = 0; i < fencedBlocks.length; i += 1) {
    out = out.replace(`@@LIONBLOCK${i}@@`, fencedBlocks[i] ?? "");
  }

  return out
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
};

/**
 * Generates `docs/llms.txt`: a concise, structured index of Lion for AI agents
 * following the llms.txt convention.
 */
export const renderLlmsTxt = (
  groups: readonly LlmsKindGroup[],
  versions: PackageVersions
): string => {
  const docSections = groups
    .map((group) => {
      const items = group.docs
        .map(
          (doc) =>
            `- [${doc.title}](${SITE_URL}/docs.html#${doc.id}): ${doc.summary}`
        )
        .join("\n");
      return `### ${group.title}\n\n${items}`;
    })
    .join("\n\n");

  return `# Lion

> Lion is a JSON-based Lisp with a built-in Datalog logic database, an exact symbolic solver and proof kernel, and an Effect v4 runtime. Every Lion program is valid JSON — storable in a database, diffable in Git, verifiable statically with \`lion check\`, and evaluable in memory or in a browser Web Worker.

Full reference in one file: ${SITE_URL}/llms-full.txt
Interactive documentation: ${SITE_URL}/docs.html
Changelog: ${SITE_URL}/changelog.html
Repository: ${REPO_URL}

## Core Syntax Rules (Read First)

- Every program is valid JSON. No separate parser.
- Arrays are calls: \`["number/add", 1, 2]\` -> \`3\`. Empty array \`[]\` evaluates to itself.
- Literal lists must use \`["quote", [1, 2]]\` or \`["array/make", 1, 2]\`.
- Strings resolve to bindings declared in an enclosing scope (stdlib, environment, \`define\`, \`relation\`, \`schema\`, lambda params); undeclared strings evaluate to themselves, EXCEPT:
  - \`"?name"\` is a logic variable (\`"?_"\` is anonymous).
  - A misspelled \`"module/name"\` (e.g. \`"number/ad"\`) is an error. Use \`["quote", "name"]\` when you mean a literal string that collides with a binding or variable.
- Objects preserve their keys and evaluate each value.
- Numbers use exact rational/decimal arithmetic (no floating-point rounding drift).
- Always run \`lion check\` on generated programs before executing them to catch arity errors, typos, unreachable \`match\` branches, and unsafe rules with JSON-pointer locations.

## Packages

- \`@lionlang/core\` (v${versions.core}): Evaluator, sandbox metering & permissions (\`safeStdlib\`, \`runWithMetrics\`), WAL journal with branching/OCC (\`JournaledDatabase\`), JSON Schema export, RFC 6902 autofix, Ed25519 \`ProofEnvelope\`, profiler, Datalog logic engine, symbolic solver (\`proof/prove\`, \`proof/bounds\`, \`proof/rules\`, \`proof/sensitivity\`, \`proof/valid?\`), and graph algorithms (\`graph/\`).
- \`@lionlang/ui\` (v${versions.ui}): Declarative, interactive, and streaming UI bindings (\`ui/stack\`, \`ui/card\`, \`ui/metric\`, \`ui/alert\`, \`ui/table\`, \`ui/slider\`, \`ui/input\`, \`ui/select\`, \`ui/toggle\`, \`ui/button\`, \`ui/why\`, \`ui/proof\`, \`ui/chart\`, \`ui/timeline\`, \`ui/diff\`, \`ui/source\`) plus a zero-dependency DOM renderer (\`@lionlang/ui/dom\`) and stateful \`createUiSession()\`.
- \`@lionlang/cli\` (v${versions.cli}): The \`lion\` CLI — evaluate files/stdin/\`-e\`, host \`lion mcp\` (JSON-RPC 2.0) and \`lion serve\` (HTTP+SSE with \`/v1/watch\`), persist logic databases (\`--database\`), static check & lint (\`lion check\`), inspect/diff databases (\`lion inspect\`, \`lion diff --derived\`), serve the Fold Map visual graph editor (\`lion repl\`), and emit a browser Web Worker (\`lion worker\`).
- \`@lionlang/typesafe-ai\` (v${versions.typesafeAi}): Bindings for TypeSafe AI's Jev judgment primitives (\`typesafe/noul\`, \`typesafe/choice\`, \`typesafe/score\`, \`typesafe/system-one\`).

## Quick Start

### TypeScript / Effect

\`\`\`bash
npm install @lionlang/core effect
# or: bun add @lionlang/core effect
\`\`\`

\`\`\`ts
import { Effect } from "effect";
import { run } from "@lionlang/core/evaluation/evaluate";
import { stdlib } from "@lionlang/core/modules";

const result = await Effect.runPromise(
  run(["number/add", 1, 2], { ...stdlib, taxRate: 0.08 })
);
\`\`\`

### CLI

\`\`\`bash
npx @lionlang/cli -e '["number/add", 1, 2]'
npx @lionlang/cli check program.json
npx @lionlang/cli setup.json --database store.json
npx @lionlang/cli inspect store.json --derived
npx @lionlang/cli diff before.json after.json --derived
npx @lionlang/cli repl
npx @lionlang/cli worker > lion-worker.js
\`\`\`

## Agent Skills

Install Lion's official agent skills into Claude Code, Codex, Cursor, or any skills-compatible agent:

\`\`\`bash
npx skills add andrueandersoncs/lion
\`\`\`

- **lion-research** (${REPO_URL}/tree/main/skills/lion-research): Turn deep research, due diligence, or incident timelines into a proof-building Lion logic model with verbatim source quotes, contradiction/restatement detection, exact solver bounds, and a self-contained interactive \`explorer.html\`.
- **lion-reasoning** (${REPO_URL}/tree/main/skills/lion-reasoning): Content-hashed working memory for coding agents — tracks observations against file hashes, detects stale evidence and contradicted hypotheses across long debugging, auditing, or optimization sessions.

## High-Leverage Use Cases

1. **Dynamic App Config & Validation**: Store schemas, pricing rules, and validation lambdas in Postgres JSONB or Git. Validate user-authored rules with \`lion check\`, evaluate in-memory on Effect, and edit visually in Fold Map.
2. **Verifiable Authorization & Business Policies**: Express RBAC/ReBAC and compliance rules in Datalog + lambdas. Get exact \`why\` explanations for every allow/deny, test changes with \`assuming\`, enforce \`invariant\`s, and formally prove universal properties with \`proof/prove\` + \`proof/valid?\`.
3. **Knowledge Bases, Ontologies & Deep Research Artifacts**: Model entities, relations, and quoted claims. Run \`graph/pageRank\`, \`graph/shortestPath\`, \`graph/cycles\`, \`graph/dominators\`, and \`graph/influence\`; measure epistemic fragility with \`proof/sensitivity\`; save via \`snapshot\`; ship live browser artifacts with \`lion worker\`.
4. **Safe Logic for AI Agents**: Have LLMs emit JSON Lion programs instead of raw JS/Python; verify with \`lion check\`; use \`proof/bounds\` and \`proof/prove\` for exact math/constraints; combine with \`@lionlang/typesafe-ai\` for hybrid neural-symbolic workflows.

## Documentation

${docSections}
`;
};

/**
 * Generates `docs/llms-full.txt`: the `llms.txt` index followed by every
 * documentation page rendered to clean Markdown with verified example outputs.
 */
export const renderLlmsFullTxt = (
  llmsTxt: string,
  docs: readonly LlmsDoc[]
): string => {
  const renderedDocs = docs.map((doc) => {
    const body = htmlToMarkdown(doc.rawBody, doc.examples);
    return [
      "---",
      "",
      `## ${doc.title}`,
      "",
      `URL: ${SITE_URL}/docs.html#${doc.id}`,
      `Section: ${doc.kindTitle} (${doc.kindLabel})`,
      "",
      `> ${doc.summary}`,
      "",
      body,
    ].join("\n");
  });

  return `${llmsTxt.trimEnd()}\n\n${renderedDocs.join("\n\n")}\n`;
};
